package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
)

// WritePLY writes an ASCII PLY carrying positions and the blended normals so
// downstream tools can inspect the corrected smile-line shading.
func WritePLY(dir, name string, mesh *Mesh) (string, error) {
	path := filepath.Join(dir, name+".ply")
	file, err := os.Create(path)
	if err != nil {
		return "", err
	}
	defer file.Close()

	w := bufio.NewWriterSize(file, 1<<16)
	header := "ply\n" +
		"format ascii 1.0\n" +
		"comment generated by facemorph (Go standard library only)\n" +
		"element vertex %d\n" +
		"property float x\n" +
		"property float y\n" +
		"property float z\n" +
		"property float nx\n" +
		"property float ny\n" +
		"property float nz\n" +
		"element face %d\n" +
		"property list uchar int vertex_indices\n" +
		"end_header\n"
	if _, err := fmt.Fprintf(w, header, len(mesh.Positions), len(mesh.Tris)); err != nil {
		return "", err
	}

	for i, position := range mesh.Positions {
		normal := mesh.Normals[i]
		if _, err := fmt.Fprintf(w,
			"%.6f %.6f %.6f %.6f %.6f %.6f\n",
			position.X, position.Y, position.Z,
			normal.X, normal.Y, normal.Z); err != nil {
			return "", err
		}
	}
	for _, tri := range mesh.Tris {
		if _, err := fmt.Fprintf(w, "3 %d %d %d\n", tri[0], tri[1], tri[2]); err != nil {
			return "", err
		}
	}
	if err := w.Flush(); err != nil {
		return "", err
	}
	return path, nil
}
